package com.linkcar.common.utils.conf;/** * 版权：Copyright xxx. All Rights Reserved. * 描述详情: XXXX * 创建者： Z·Shuai * 创建时间：2018/8/7 10:28 */public class ConfFactory {    public static BaseConf createConf(String type){        BaseConf wxinBaseConf;        if("WxinConf_Pro".equals(type)){            wxinBaseConf = new WxinCnfPro();        }else if("WxinConf_Test".equals(type)) {            wxinBaseConf = new WxinCnfTest();        }else {            wxinBaseConf = new WxinCnfTest();        }        return wxinBaseConf;    }}